entries[1254929] = { ["name"] = "Dämmerschleier", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer ewige Töter hüllt sich in arkane Energie, was den erlittenen Schaden um 25% verringert und Angreifern 15 Sek. lang 2 Arkanschaden zufügt, wenn sie getroffen werden." }
entries[1254960] = { ["name"] = "Aufholen", ["text"] = "Sofort\nHört Euch eine Geschichte an." }
entries[1255153] = { ["name"] = "Rückblick verlassen", ["text"] = "Sofort\nGeschichte beenden und den Rückblick verlassen, um in die normale Welt zurückzukehren." }
entries[1255154] = { ["name"] = "Aufholerfahrung verlassen", ["text"] = "Sofort\nWenn Ihr Euch verirrt habt, nutzt \"Im Folianten nachsehen\", um ins richtige Gebiet teleportiert zu werden.\n\nWenn Ihr die Aufholerfahrung verlasst, werdet Ihr zurück in Eure Hauptstadt teleportiert. Ihr könnt diese Aufholkampagne jederzeit fortsetzen – es sei denn, Ihr beginnt eine andere.\n\nMöchtet Ihr fortfahren?" }
entries[1255155] = { ["name"] = "Aufholerfahrung verlassen", ["text"] = "Sofort\nBeendet die Lehrensucherkampagne und kehrt in Eure Hauptstadt zurück." }
entries[1255159] = { ["name"] = "Mechanischer Panther-Prototyp MK-0", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Als die Bürger von Lorenhall das unterirdische Labor von Garbagio aufbrachen, war das Gebrüll der eingesperrten Bestien ohrenbetäubend. Die Technologie der Düsternisverschmolzenen hat diese Panther mit Kampfmodulen ausgestattet, die ihnen übernatürliche Stärke und Geschwindigkeit verleihen. Bilgewasser-Ingenieure programmierten sie speziell für Champions um, die in K'aresh kämpfen. Vergesst nicht, die Module vor dem Einsatz beim Podium der Transformation auszutauschen.\"\nWoW-Shop" }
entries[1255165] = { ["name"] = "Im Folianten nachsehen", ["text"] = "Sofort 4 sek. Abklingzeit\nBefragt den Folianten, wenn Ihr nicht wisst, wohin Ihr als Nächstes gehen sollt, oder um mehr Informationen zu erhalten." }
entries[1255179] = { ["name"] = "Stählerner Panther-Prototyp MK-0", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die ersten Soldaten der Eisernen Horde, die das Dunkle Portal durchquerten, erbeuteten einen grimmigen Nachtsäbler. Handwerker des Schwarzfelsklans statteten ihn mit einer Magmapanzerung aus und verwandelten ihn in eine Kampfwaffe. Beim Podium der Transformation können Champions seine Teile an ihren Kampfstil anpassen, um das Schlachtfeld zu dominieren.\"\nWoW-Shop" }
