entries[1255245] = { ["name"] = "Zwielichtstreich", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer ewige Töter durchschreitet das Zwielicht, um hinter seinem Ziel aufzutauchen und einen Streich auszuführen, was 2 körperlichen Schaden und zusätzlich 9 Sek. lang alle 1.5 Sek. 0 Blutungsschaden verursacht." }
entries[1255246] = { ["name"] = "Sternfunkelnder Netherdrache", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Flugreittier oder gibt es wieder frei.\n\"Nachdem er Euch bis ans Ende der Scherbenwelt und noch weiter getragen hat, fühlte sich der Netherschwingendrache am Ende auch zu den blauen Himmeln von Azeroth hingezogen.\"\nPromotion:\nBurning Crusade Classic" }
entries[1255264] = { ["name"] = "Teufelsgeweihter Giftbrutbezwinger", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren teufelsgeweihten Giftbrutbezwinger oder gibt ihn wieder frei. Dieses Reittier steht nur Todesrittern zur Verfügung.\n\"Diese fliegende Vereinigung der Mächte des Todes und der Hölle zerfetzt die Lüfte mit ihrem schaurigen Kreischen.\"\nWeltereignis:\nWoW Remix: Legion" }
