entries[1255456] = { ["name"] = "Teufelsgeweihter Wolfsfalke", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren teufelsgeweihten Wolfsfalken oder gibt ihn wieder frei. Dieses Reittier steht nur Jägern zur Verfügung.\n\"Gezeichnet durch den Krieg auf den Verheerten Inseln, verdient dieser Wolfsfalke ein gutes Zuhause.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1255463] = { ["name"] = "Teufelsgeweihte Scheibe des Erzmagiers", ["text"] = "Wirken in 1.5 sek.\nBeschwört Eure teufelsgeweihte Scheibe des Erzmagiers oder gibt sie wieder frei. Dieses Reittier steht nur Magiern zur Verfügung.\n\"Einige Magier sagen, dämonische Magie sei \"instabil\" oder \"korrumpierend\" oder \"verboten\". Einige Magier liegen falsch.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1255467] = { ["name"] = "Teufelsgeweihter Begleiter des Großmeisters", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren teufelsgeweihten Begleiter des Großmeisters oder gibt ihn wieder frei. Dieses Reittier steht nur Mönchen zur Verfügung.\n\"Das verzerrte Antlitz eines geliebten Begleiters.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1255471] = { ["name"] = "Teufelsgeweihtes Streitross des Hochlords", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euer teufelsgeweihtes Streitross des Hochlords oder gibt es wieder frei. Dieses Reittier steht nur Paladinen zur Verfügung.\n\"Dieses Pferd wurde auf ewig durch die verderbte Magie der Legion gezeichnet.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1255475] = { ["name"] = "Teufelsgeweihter Sucher des Hohepriesters", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren teufelsgeweihten Sucher des Hohepriesters oder gibt ihn wieder frei. Dieses Reittier steht nur Priestern zur Verfügung.\n\"Dieser dämonisch verderbte gefiederte Freund schlägt in einem frenetischen Tempo mit den Flügeln, um sich weit vom Getümmel am Boden abzuheben.\"\nWeltereignis:\nWoW Remix: Legion" }
