entries[1263369] = { ["name"] = "Himmelspfotenglimmerpelz", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Das Fell eines Glimmerpelzes nimmt die Eigenschaften seiner Umgebung an, ähnlich wie eine Tarnung. Muster eines strahlend blauen Himmels und majestätischer weißer Wolken haben diesem Glimmerpelz den Spitznamen \"Himmelspfote\" eingebracht.\"\nVerkäufer:\nSammler Ta'steld\nZone:\nOribos\nKosten:\n5.000" }
