entries[1263877] = { ["name"] = "Rute des Drustverzauberers", ["text"] = "Wirken in 2 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nDüsterkiefernholz (6), Umbralsplitter (4), Raues Leder (2), Kalzifizierter Knochen\nErschafft eine Rute des Drustverzauberers, die in Eurem Haus platziert oder im Auktionshaus verkauft werden kann.\nBerufsausbilder:\nVerzauberkunst von Battle for Azeroth (140)\nKosten:\n4\n\n1\nRute des Drustverzauberers\nBehausungsdekoration\nWird bei Benutzung gebunden\nBenutzen: Fügt diese Dekoration zu Eurer Haustruhe hinzu." }
